class BTree:
    class _Node:
        __slots__ = ("keys", "children")

        def __init__(self):
            self.keys = []
            self.children = []

    def __init__(self, t: int):
        self.t = t
        self.root = self._Node()

    @staticmethod
    def _slot(node, key):
        i = 0
        while i < len(node.keys) and key > node.keys[i]:
            i += 1
        return i

    def search(self, key: int) -> bool:
        node = self.root
        while True:
            i = self._slot(node, key)
            if i < len(node.keys) and node.keys[i] == key:
                return True
            if not node.children:
                return False
            node = node.children[i]

    def _split_child(self, parent, i):
        t = self.t
        full = parent.children[i]
        right = self._Node()
        right.keys = full.keys[t:]
        mid = full.keys[t - 1]
        full.keys = full.keys[: t - 1]
        if full.children:
            right.children = full.children[t:]
            full.children = full.children[:t]
        parent.keys.insert(i, mid)
        parent.children.insert(i + 1, right)

    def _insert_nonfull(self, node, key):
        i = self._slot(node, key)
        if not node.children:
            node.keys.insert(i, key)
            return
        if len(node.children[i].keys) == 2 * self.t - 1:
            self._split_child(node, i)
            if key > node.keys[i]:
                i += 1
        self._insert_nonfull(node.children[i], key)

    def insert(self, key: int) -> bool:
        if self.search(key):
            return False
        if len(self.root.keys) == 2 * self.t - 1:
            grown = self._Node()
            grown.children = [self.root]
            self.root = grown
            self._split_child(grown, 0)
        self._insert_nonfull(self.root, key)
        return True

    def height(self) -> int:
        if not self.root.keys:
            return 0
        h, node = 1, self.root
        while node.children:
            h += 1
            node = node.children[0]
        return h

    def serialize(self) -> list[list[int]]:
        if not self.root.keys:
            return []
        out, level = [], [self.root]
        while level:
            nxt = []
            for node in level:
                out.append(list(node.keys))
                nxt.extend(node.children)
            level = nxt
        return out

import bisect


class BTree:
    class _Node:
        __slots__ = ("keys", "children")

        def __init__(self):
            self.keys = []
            self.children = []

    def __init__(self, t: int):
        self.t = t
        self.root = self._Node()

    def search(self, key: int) -> bool:
        node = self.root
        while True:
            i = bisect.bisect_left(node.keys, key)
            if i < len(node.keys) and node.keys[i] == key:
                return True
            if not node.children:
                return False
            node = node.children[i]

    def _split_child(self, parent, i):
        t = self.t
        full = parent.children[i]
        right = self._Node()
        right.keys = full.keys[t:]
        mid = full.keys[t - 1]
        full.keys = full.keys[: t - 1]
        if full.children:
            right.children = full.children[t:]
            full.children = full.children[:t]
        parent.keys.insert(i, mid)
        parent.children.insert(i + 1, right)

    def insert(self, key: int) -> bool:
        if self.search(key):
            return False
        full = 2 * self.t - 1
        if len(self.root.keys) == full:
            grown = self._Node()
            grown.children = [self.root]
            self.root = grown
            self._split_child(grown, 0)
        node = self.root
        while node.children:
            i = bisect.bisect_left(node.keys, key)
            if len(node.children[i].keys) == full:
                self._split_child(node, i)
                if key > node.keys[i]:
                    i += 1
            node = node.children[i]
        bisect.insort(node.keys, key)
        return True

    def height(self) -> int:
        if not self.root.keys:
            return 0
        h, node = 1, self.root
        while node.children:
            h += 1
            node = node.children[0]
        return h

    def serialize(self) -> list[list[int]]:
        if not self.root.keys:
            return []
        out, level = [], [self.root]
        while level:
            nxt = []
            for node in level:
                out.append(list(node.keys))
                nxt.extend(node.children)
            level = nxt
        return out
